// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    ERCDDAToken c;
    function setUp() public { c = new ERCDDAToken(0, "Test", "TST"); }
    function testFuzz_property(uint256 mintAmount, uint256 burnAmount) public {
        vm.assume(mintAmount > 0 && burnAmount > 0);
        vm.assume(mintAmount <= type(uint256).max / 2);
        vm.assume(burnAmount <= mintAmount);

        address owner = address(this);
        c.mintToken(owner, mintAmount);
        c.burn(burnAmount);

        uint256 actualTotal = c.totalSupply();
        uint256 ownerBalance = c.balanceOf(owner);
        assertTrue(actualTotal == ownerBalance);
    }
}
